85	static bool esp_graphics_overlap(FAR const struct esp_graphics_buffer_s *a,
86	                                 FAR const struct esp_graphics_buffer_s *b)
87	{
88	  uintptr_t start_a = (uintptr_t)a->data;
89	  uintptr_t start_b = (uintptr_t)b->data;
90	
91	  return start_a < start_b + b->size && start_b < start_a + a->size;
92	}
