94	void esp_graphics_descriptor(FAR dma2d_descriptor_t *desc,
95	                             FAR const struct esp_graphics_buffer_s *buffer,
96	                             uint32_t x, uint32_t y,
97	                             uint32_t width, uint32_t height)
98	{
99	  unsigned int bpp = esp_graphics_bpp(buffer->format);
100	
101	  memset(desc, 0, sizeof(*desc));
102	  desc->owner = DMA2D_DESCRIPTOR_BUFFER_OWNER_DMA;
103	  desc->suc_eof = 1;
104	  desc->dma2d_en = 1;
105	  desc->hb_length = width;
106	  desc->vb_size = height;
107	  desc->ha_length = buffer->stride / bpp;
108	  desc->va_size = buffer->height;
109	  desc->pbyte = bpp + 1;
110	  desc->x = x;
111	  desc->y = y;
112	  desc->buffer = buffer->data;
113	}
