156	  dma2d_ll_tx_enable_auto_write_back(dev, channel, false);
157	  dma2d_ll_tx_enable_page_bound_wrap(dev, channel, true);
158	  dma2d_ll_tx_enable_descriptor_burst(dev, channel, true);
159	  dma2d_ll_tx_set_data_burst_length(dev, channel,
