60	int esp_graphics_check_buffer(FAR const struct esp_graphics_buffer_s *buffer,
61	                              uint32_t x, uint32_t y,
62	                              uint32_t width, uint32_t height)
63	{
64	  uintptr_t address = (uintptr_t)buffer->data;
65	  uintptr_t last;
66	  int ret = esp_graphics_buffer_bounds(buffer, x, y, width, height);
67	
68	  if (ret < 0)
69	    {
70	      return ret;
71	    }
72	
73	  last = address + buffer->size - 1;
74	  if (!((esp_ptr_dma_capable((void *)address) &&
75	         esp_ptr_dma_capable((void *)last)) ||
76	        (esp_ptr_external_ram((void *)address) &&
77	         esp_ptr_external_ram((void *)last))))
78	    {
79	      return -EFAULT;
80	    }
81	
82	  return OK;
83	}
84	
85	static bool esp_graphics_overlap(FAR const struct esp_graphics_buffer_s *a,
86	                                 FAR const struct esp_graphics_buffer_s *b)
87	{
88	  uintptr_t start_a = (uintptr_t)a->data;
89	  uintptr_t start_b = (uintptr_t)b->data;
90	
91	  return start_a < start_b + b->size && start_b < start_a + a->size;
92	}
93	
94	void esp_graphics_descriptor(FAR dma2d_descriptor_t *desc,
95	                             FAR const struct esp_graphics_buffer_s *buffer,
96	                             uint32_t x, uint32_t y,
97	                             uint32_t width, uint32_t height)
98	{
99	  unsigned int bpp = esp_graphics_bpp(buffer->format);
100	
101	  memset(desc, 0, sizeof(*desc));
102	  desc->owner = DMA2D_DESCRIPTOR_BUFFER_OWNER_DMA;
103	  desc->suc_eof = 1;
104	  desc->dma2d_en = 1;
105	  desc->hb_length = width;
106	  desc->vb_size = height;
107	  desc->ha_length = buffer->stride / bpp;
108	  desc->va_size = buffer->height;
109	  desc->pbyte = bpp + 1;
110	  desc->x = x;
111	  desc->y = y;
112	  desc->buffer = buffer->data;
113	}
