146	void esp_graphics_tx(unsigned int channel, dma2d_trigger_peripheral_t periph,
147	                      int select, FAR dma2d_descriptor_t *desc)
148	{
149	  FAR dma2d_dev_t *dev = DMA2D_LL_GET_HW(0);
150	
151	  dma2d_ll_tx_connect_to_periph(dev, channel, periph, select);
152	  dma2d_ll_tx_enable_dscr_port(dev, channel,
153	                               periph == DMA2D_TRIG_PERIPH_PPA_SRM);
154	  dma2d_ll_tx_enable_owner_check(dev, channel, true);
155	  dma2d_ll_tx_enable_eof_mode(dev, channel, true);
156	  dma2d_ll_tx_enable_auto_write_back(dev, channel, false);
157	  dma2d_ll_tx_enable_page_bound_wrap(dev, channel, true);
158	  dma2d_ll_tx_enable_descriptor_burst(dev, channel, true);
159	  dma2d_ll_tx_set_data_burst_length(dev, channel,
160	                                    DMA2D_DATA_BURST_LENGTH_64);
161	  dma2d_ll_tx_set_macro_block_size(dev, channel,
162	                                   DMA2D_MACRO_BLOCK_SIZE_NONE);
163	  dma2d_ll_tx_configure_color_space_conv(dev, channel, DMA2D_CSC_TX_NONE);
164	  dma2d_ll_tx_enable_interrupt(dev, channel, DMA2D_TX_ERRORS, true);
165	  dma2d_ll_tx_set_desc_addr(dev, channel, (uintptr_t)desc);
166	}
167	
168	void esp_graphics_rx(dma2d_trigger_peripheral_t periph, int select,
169	                      FAR dma2d_descriptor_t *desc)
170	{
171	  FAR dma2d_dev_t *dev = DMA2D_LL_GET_HW(0);
172	
173	  dma2d_ll_rx_connect_to_periph(dev, 0, periph, select);
174	  dma2d_ll_rx_enable_dscr_port(dev, 0, periph == DMA2D_TRIG_PERIPH_PPA_SRM);
175	  dma2d_ll_rx_set_auto_return_owner(dev, 0,
176	                                    DMA2D_DESCRIPTOR_BUFFER_OWNER_CPU);
177	  dma2d_ll_rx_enable_reorder(dev, 0, false);
178	  dma2d_ll_rx_enable_owner_check(dev, 0, true);
179	  dma2d_ll_rx_enable_page_bound_wrap(dev, 0, true);
180	  dma2d_ll_rx_enable_descriptor_burst(dev, 0, true);
181	  dma2d_ll_rx_set_data_burst_length(dev, 0, DMA2D_DATA_BURST_LENGTH_64);
182	  dma2d_ll_rx_set_macro_block_size(dev, 0, DMA2D_MACRO_BLOCK_SIZE_NONE);
183	  dma2d_ll_rx_configure_color_space_conv(dev, 0, DMA2D_CSC_RX_NONE);
184	  dma2d_ll_rx_enable_interrupt(dev, 0,
185	                               DMA2D_RX_ERRORS | DMA2D_LL_EVENT_RX_SUC_EOF,
186	                               true);
187	  dma2d_ll_rx_set_desc_addr(dev, 0, (uintptr_t)desc);
188	}
189	
190	static int esp_dma2d_interrupt(int irq, FAR void *context, FAR void *arg)
191	{
192	  FAR struct esp_graphics_s *priv = arg;
193	  FAR dma2d_dev_t *dev = DMA2D_LL_GET_HW(0);
194	  uint32_t rx = dma2d_ll_rx_get_interrupt_status(dev, 0);
195	  uint32_t tx0 = dma2d_ll_tx_get_interrupt_status(dev, 0);
196	  uint32_t tx1 = dma2d_ll_tx_get_interrupt_status(dev, 1);
197	  irqstate_t flags;
198	  uint32_t ppa = 0;
199	
200	#ifdef CONFIG_ESP32P4_PPA
201	  ppa = esp_ppa_errors();
202	#endif
203	
204	  dma2d_ll_rx_clear_interrupt_status(dev, 0, rx);
205	  dma2d_ll_tx_clear_interrupt_status(dev, 0, tx0);
206	  dma2d_ll_tx_clear_interrupt_status(dev, 1, tx1);
207	  flags = spin_lock_irqsave(&priv->lock);
208	  if (priv->busy && !priv->completed &&
209	      ((rx & (DMA2D_RX_ERRORS | DMA2D_LL_EVENT_RX_SUC_EOF)) != 0 ||
210	       ((tx0 | tx1) & DMA2D_TX_ERRORS) != 0 || ppa != 0))
211	    {
212	      priv->result = ((rx & DMA2D_RX_ERRORS) != 0 ||
213	                      ((tx0 | tx1) & DMA2D_TX_ERRORS) != 0 ||
214	                      ppa != 0) ? -EIO : OK;
215	      priv->completed = true;
216	      nxsem_post(&priv->done);
217	    }
218	
219	  spin_unlock_irqrestore(&priv->lock, flags);
220	  return OK;
221	}
222	
223	int esp_graphics_initialize(void)
224	{
225	  static const int sources[] =
226	  {
227	    ETS_DMA2D_IN_CH0_INTR_SOURCE,
228	    ETS_DMA2D_OUT_CH0_INTR_SOURCE,
229	    ETS_DMA2D_OUT_CH1_INTR_SOURCE,
230	#ifdef CONFIG_ESP32P4_PPA
231	    ETS_PPA_INTR_SOURCE
232	#endif
233	  };
234	
235	  FAR struct esp_graphics_s *priv;
236	  int installed = 0;
237	  int ret;
238	
239	  if (up_interrupt_context())
240	    {
241	      return -EPERM;
242	    }
243	
244	  ret = nxmutex_lock(&g_initialize_lock);
245	  if (ret < 0)
246	    {
247	      return ret;
248	    }
249	
250	  if (g_graphics != NULL)
251	    {
252	      nxmutex_unlock(&g_initialize_lock);
253	      return OK;
254	    }
255	
256	  priv = kmm_zalloc(sizeof(*priv));
257	  if (priv == NULL)
258	    {
259	      ret = -ENOMEM;
260	      goto out;
261	    }
262	
263	  priv->tx = kmm_memalign(ESP_GRAPHICS_ALIGNMENT, DESC_BYTES);
264	  if (priv->tx == NULL || !esp_ptr_in_dram(priv->tx) ||
265	      !esp_ptr_in_dram((uint8_t *)priv->tx + DESC_BYTES - 1))
266	    {
267	      ret = -ENOMEM;
268	      goto free_priv;
269	    }
270	
271	  priv->fg = priv->tx + ESP_GRAPHICS_DESCRIPTORS;
272	  priv->rx = priv->fg + 1;
273	  spin_lock_init(&priv->lock);
274	  nxmutex_init(&priv->mutex);
275	  nxsem_init(&priv->done, 0, 0);
276	  nxsem_set_protocol(&priv->done, SEM_PRIO_NONE);
277	
278	  PERIPH_RCC_ATOMIC()
279	    {
280	      dma2d_ll_enable_bus_clock(0, true);
281	    }
282	
283	  esp_graphics_reset();
284	  while (installed < nitems(sources))
285	    {
286	      ret = esp_setup_irq_with_flags(sources[installed],
287	                                     ESP_INTR_FLAG_LEVEL1,
288	                                     esp_dma2d_interrupt, priv);
289	      if (ret < 0)
290	        {
291	          goto free_irqs;
292	        }
293	
294	      up_enable_irq(ESP_SOURCE2IRQ(sources[installed]));
295	      installed++;
296	    }
297	
298	  g_graphics = priv;
299	  ret = OK;
300	  goto out;
301	
302	free_irqs:
303	  while (installed > 0)
304	    {
305	      installed--;
306	      esp_teardown_irq(sources[installed], 0);
307	    }
308	
309	  PERIPH_RCC_ATOMIC()
310	    {
311	      dma2d_ll_enable_bus_clock(0, false);
312	    }
313	
314	#ifdef CONFIG_ESP32P4_PPA
315	  esp_ppa_uninitialize();
316	#endif
317	
318	  nxsem_destroy(&priv->done);
319	  nxmutex_destroy(&priv->mutex);
320	free_priv:
321	  kmm_free(priv->tx);
322	  kmm_free(priv);
323	out:
324	  nxmutex_unlock(&g_initialize_lock);
325	  return ret;
326	}
327	
328	static int esp_graphics_validate(FAR const struct esp_graphics_job_s *job)
329	{
330	  int ret;
331	
332	  if (job->operation != ESP_GRAPHICS_COPY)
333	    {
334	#ifdef CONFIG_ESP32P4_PPA
335	      ret = esp_ppa_validate(job);
336	#else
337	      ret = -ENOTSUP;
338	#endif
339	    }
340	  else
341	    {
342	      if (job->src.format != ESP_GRAPHICS_RGB565 ||
343	          job->dst.format != ESP_GRAPHICS_RGB565 ||
344	          job->height > ESP_GRAPHICS_DESCRIPTORS * ESP_GRAPHICS_BAND_ROWS)
345	        {
346	          return -ENOTSUP;
347	        }
348	
349	      ret = esp_graphics_check_buffer(&job->src, job->src_x, job->src_y,
350	                                      job->width, job->height);
351	      if (ret == OK)
352	        {
353	          ret = esp_graphics_check_buffer(&job->dst, job->dst_x, job->dst_y,
354	                                          job->width, job->height);
355	        }
356	    }
357	
358	  if (ret < 0)
359	    {
360	      return ret;
361	    }
362	
363	  if ((job->operation != ESP_GRAPHICS_FILL &&
364	       esp_graphics_overlap(&job->src, &job->dst)) ||
365	      (job->operation == ESP_GRAPHICS_BLEND &&
366	       esp_graphics_overlap(&job->foreground, &job->dst)))
367	    {
368	      return -EINVAL;
369	    }
370	
371	  return OK;
372	}
373	
374	static void esp_dma2d_prepare(FAR struct esp_graphics_s *priv)
375	{
376	  FAR const struct esp_graphics_job_s *job = &priv->job;
377	  unsigned int count = (job->height + ESP_GRAPHICS_BAND_ROWS - 1) /
378	                       ESP_GRAPHICS_BAND_ROWS;
379	  unsigned int i;
380	  unsigned int y;
381	  unsigned int rows;
382	
383	  for (i = 0; i < count; i++)
384	    {
385	      y = i * ESP_GRAPHICS_BAND_ROWS;
386	      rows = MIN(ESP_GRAPHICS_BAND_ROWS, job->height - y);
387	      esp_graphics_descriptor(&priv->tx[i].dma, &job->src,
388	                               job->src_x, job->src_y + y, job->width, rows);
389	      esp_graphics_descriptor(&priv->rx[i].dma, &job->dst,
390	                               job->dst_x, job->dst_y + y, job->width, rows);
391	      if (i + 1 < count)
392	        {
393	          priv->tx[i].dma.next = &priv->tx[i + 1].dma;
394	          priv->rx[i].dma.next = &priv->rx[i + 1].dma;
395	          priv->tx[i].dma.suc_eof = 0;
396	        }
397	
398	      priv->rx[i].dma.suc_eof = 0;
399	    }
400	
401	  esp_graphics_tx(0, DMA2D_TRIG_PERIPH_M2M, 4, &priv->tx[0].dma);
402	  esp_graphics_rx(DMA2D_TRIG_PERIPH_M2M, 4, &priv->rx[0].dma);
403	}
404	
405	static int esp_graphics_cache(FAR const struct esp_graphics_buffer_s *buffer,
406	                               int flags)
407	{
408	  return esp_cache_msync(buffer->data, buffer->size, flags) == ESP_OK ?
409	         OK : -EIO;
410	}
411	
412	int esp_graphics_submit(FAR const struct esp_graphics_job_s *job,
413	                        FAR uint32_t *ticket)
414	{
415	  FAR struct esp_graphics_s *priv = g_graphics;
416	  irqstate_t flags;
417	  int ret;
418	
419	  if (priv == NULL)
420	    {
421	      return -ENODEV;
422	    }
423	
424	  if (job == NULL || ticket == NULL || up_interrupt_context())
425	    {
426	      return -EINVAL;
427	    }
428	
429	  ret = nxmutex_trylock(&priv->mutex);
430	  if (ret < 0)
431	    {
432	      return -EBUSY;
433	    }
434	
435	  if (priv->busy)
436	    {
437	      ret = -EBUSY;
438	      goto out;
439	    }
440	
441	  priv->job = *job;
442	  job = &priv->job;
443	  ret = esp_graphics_validate(job);
444	  if (ret < 0)
445	    {
446	      goto out;
447	    }
448	
449	  ret = esp_graphics_cache(&job->dst, ESP_CACHE_MSYNC_FLAG_DIR_C2M |
450	                                      ESP_CACHE_MSYNC_FLAG_INVALIDATE);
451	  if (ret == OK && job->operation != ESP_GRAPHICS_FILL)
452	    {
453	      ret = esp_graphics_cache(&job->src, ESP_CACHE_MSYNC_FLAG_DIR_C2M);
454	    }
455	
456	  if (ret == OK && job->operation == ESP_GRAPHICS_BLEND)
457	    {
458	      ret = esp_graphics_cache(&job->foreground,
459	                                ESP_CACHE_MSYNC_FLAG_DIR_C2M);
460	    }
461	
462	  if (ret < 0)
463	    {
464	      goto out;
465	    }
466	
467	  esp_graphics_reset();
468	  memset(priv->tx, 0, DESC_BYTES);
469	  if (job->operation == ESP_GRAPHICS_COPY)
470	    {
471	      esp_dma2d_prepare(priv);
472	    }
473	#ifdef CONFIG_ESP32P4_PPA
474	  else
475	    {
476	      ret = esp_ppa_prepare(priv);
477	      if (ret < 0)
478	        {
479	          goto out;
480	        }
481	    }
482	#endif
483	
484	  if (esp_cache_msync(priv->tx, DESC_BYTES,
485	                      ESP_CACHE_MSYNC_FLAG_DIR_C2M) != ESP_OK)
486	    {
487	      ret = -EIO;
488	      goto out;
489	    }
490	
491	  while (nxsem_trywait(&priv->done) == OK);
492	  flags = spin_lock_irqsave(&priv->lock);
493	  priv->ticket++;
494	  if (priv->ticket == 0)
495	    {
496	      priv->ticket++;
497	    }
498	
499	  *ticket = priv->ticket;
500	  priv->busy = true;
501	  priv->completed = false;
502	  priv->result = -EINPROGRESS;
503	  UP_DMB();
504	  dma2d_ll_rx_start(DMA2D_LL_GET_HW(0), 0);
505	  if (job->operation != ESP_GRAPHICS_FILL)
506	    {
507	      dma2d_ll_tx_start(DMA2D_LL_GET_HW(0), 0);
508	    }
509	
510	  if (job->operation == ESP_GRAPHICS_BLEND)
